// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 newVal, address actor) public {
        vm.assume(actor != address(0));

        // Choose an initial MinSum and initialize the contract.
        vm.prank(actor);
        c.SetMinSum(1);
        vm.prank(actor);
        c.Initialized();

        // After initialization, SetMinSum must be frozen: the call must revert.
        vm.prank(actor);
        bool ok;
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: once initialized, any SetMinSum attempt reverts,
        // so MinSum can never be changed afterwards. The mutant (guard deleted)
        // lets the call succeed and overwrites MinSum with newVal.
        assertTrue(!ok && c.MinSum() == 1);
    }
}
